using System;using System.IO;using System.Text;using System.Collections;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckFishing {
public sealed class FishingProbe:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 [RuntimeInitializeOnLoadMethod]static void Boot(){bool run=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsFishing")>=0;
#if UNITY_EDITOR
 run|=UnityEditor.SessionState.GetBool("LWS.FishingProbe",false);UnityEditor.SessionState.SetBool("LWS.FishingProbe",false);
#endif
 if(run){var g=new GameObject("Fishing complete seeded four-AI survival acceptance");DontDestroyOnLoad(g);if(FindAnyObjectByType<SportsProbeInputIsolation>()==null)g.AddComponent<SportsProbeInputIsolation>();g.AddComponent<FishingProbe>();}}
 FishingMatch m;SportsScoreAcceptance.Tally tally;string folder;int errors;readonly StringBuilder report=new StringBuilder();void Check(bool ok,string label){report.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;File.WriteAllText(folder+"/progress.txt",report.ToString());}void Error(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;report.AppendLine("ERROR "+s);}}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("FishingEvidence");File.WriteAllText(folder+"/result.txt","RUNNING "+DateTime.UtcNow.ToString("O"));Application.logMessageReceived+=Error;yield return SportsProbeScene.Ensure<FishingMatch>("TruckFishing");m=FindAnyObjectByType<FishingMatch>();yield return null;SportsCameraOptions.Set(false);for(int difficulty=0;difficulty<3;difficulty++){m.SetupScreen();m.setup.count=4;m.NormalizeSetup();m.AllBots();m.seed=17381+difficulty*8011;for(int i=0;i<4;i++)m.setup.players[i].difficulty=(BowlingDifficulty)difficulty;tally?.Dispose();tally=new SportsScoreAcceptance.Tally(m);bool captured=false;Check(m.StartMatch()&&m.HumanViews==0&&m.cameras.Length==1,"four AI streams start without controllers difficulty="+difficulty);var parked=Array.ConvertAll(m.streams,s=>s.truck.body.position);Time.timeScale=10;float until=Time.realtimeSinceStartup+240,next=0;bool paused=false;while(!m.Finished&&Time.realtimeSinceStartup<until){if(!captured&&m.Clock>23){yield return CaptureCatch("difficulty-"+difficulty);captured=true;}if(!paused&&m.Clock>10){paused=true;m.Pause();var net=m.streams[0].NetX;double clock=m.Clock;int weight=m.rules.caught[0];yield return new WaitForSecondsRealtime(.15f);Check(m.Paused&&m.Clock==clock&&m.rules.caught[0]==weight&&m.streams[0].NetX==net,"pause preserves fish clock, net and score difficulty="+difficulty);m.Resume();Time.timeScale=10;}if(Time.realtimeSinceStartup>=next){File.WriteAllText(folder+"/progress.txt",report+"LIVE difficulty="+difficulty+" time="+m.Clock+" caught="+string.Join(",",m.rules.caught)+" missed="+string.Join(",",m.rules.missed)+" remaining="+m.rules.Remaining+" schedule="+m.ScheduleCount+" errors="+errors);next=Time.realtimeSinceStartup+2;}yield return null;}tally.Verify(slot=>m.rules.caught[slot],Check);Check(captured,"actual owned catch feedback captured difficulty="+difficulty);if(m.Finished)yield return SportsResultsAcceptance.Capture(m,Check,folder,m.ResultPlace,slot=>(double?)m.rules.caught[slot],slot=>m.rules.Winner==slot);
 Check(m.Finished&&m.rules.Complete&&m.rules.Remaining<=1,"complete actual seeded survival match difficulty="+difficulty);for(int i=0;i<4;i++){Check(m.streams[i].MaximumTravel>3&&m.rules.caught[i]>0,"same bounded AI net physically moves and catches generated fish slot="+i+" difficulty="+difficulty);Check(m.streams[i].truck.body.position==parked[i],"truck remains stationary while net moves slot="+i);Check(!m.streams[i].Overflowed,"bounded actor pool never drops fish slot="+i);}report.AppendLine("MATCH difficulty="+difficulty+" time="+m.Clock+" winner="+m.rules.Winner+" caught="+string.Join(",",m.rules.caught)+" missed="+string.Join(",",m.rules.missed)+" reasons="+string.Join(",",m.rules.reason));}tally.Dispose();tally=null;m.SetupScreen();SportsCameraOptions.Set(true);Check(m.StartMatch()&&m.HumanViews==4&&m.cameras.Length==4,"optional AI views use four real stream owners");Time.timeScale=4;float aiDeadline=Time.realtimeSinceStartup+35;while(m.Clock<18&&!m.Finished&&Time.realtimeSinceStartup<aiDeadline)yield return null;yield return CaptureCatch("four-AI-views");m.SetupScreen();SportsCameraOptions.Set(false);Check(FindObjectsByType<AudioListener>(FindObjectsInactive.Exclude).Length==1,"one spectator/split-screen listener");m.SetupScreen();Check(m.StartMatch()&&m.rules.caught[0]==0&&m.Clock==0,"repeated rematch resets clock, weights, director and pools");m.SetupScreen();report.AppendLine("ERRORS="+errors+". Native fixed-step generated-fish/swept-net gameplay with autonomous AI; rule fixtures are separate. No real hardware/human playtest or GPU benchmark.");File.WriteAllText(folder+"/result.txt",report.ToString());Debug.Log("FISHING_PROBE_COMPLETE "+report);Application.logMessageReceived-=Error;Time.timeScale=1;if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 IEnumerator CaptureCatch(string label){
 var panels=m.menus.GetComponentsInChildren<SportsScorePresentation>(true);Check(panels.Length==4,"four saved owned Heat score panels "+label);var before=Array.ConvertAll(panels,p=>p.Presented);float scale=Time.timeScale;Time.timeScale=1;int fresh=-1;float deadline=Time.realtimeSinceStartup+28;
 while(fresh<0&&!m.Finished&&Time.realtimeSinceStartup<deadline){yield return null;for(int i=0;i<panels.Length;i++)if(panels[i].Presented>before[i]){fresh=i;break;}}
 Check(fresh>=0,"fresh real accepted catch reaches its viewport "+label);if(fresh<0){Time.timeScale=scale;yield break;}
 bool enabled=m.enabled;m.enabled=false;
 try{
 yield return new WaitForSeconds(Michsky.UI.Heat.HeatUIInternalTools.GetAnimatorClipLength(panels[fresh].notificationAnimator,"Notification_In")+.03f);Time.timeScale=0;
 foreach(var panel in panels){int view=panel.viewport;bool valid=m.TryReadViewportCard(view,out int owner,out _,out _);Check(valid?panel.ViewportOwner==owner:panel.visibility.alpha==0,"notification follows actual displayed owner view="+view+" "+label);if(panel.LastPresented!=null)Check(valid&&panel.LastPresented.Slot==owner&&panel.LastPresented.MatchId==m.MatchId&&panel.LastPresented.Unit=="LB","no other participant or prior-match catch shown view="+view+" "+label);}
 Check(panels[fresh].visibility.alpha==1&&panels[fresh].notification.gameObject.activeInHierarchy,"actual owned catch is visible after the full Heat entrance "+label);
 yield return SportsWindowCapture.Save(1280,720,folder+"/"+label+"-catch-720.png");yield return SportsWindowCapture.Save(1920,1080,folder+"/"+label+"-catch-1080.png");
 }finally{m.enabled=enabled;Time.timeScale=scale;}
 }
 void OnDestroy(){tally?.Dispose();Application.logMessageReceived-=Error;Time.timeScale=1;}
#endif
}
